"""Generate follow-up claims from new runs; never change frozen measurements."""
from pathlib import Path
import json
import numpy as np
HERE=Path(__file__).resolve().parent;ROOT=HERE.parent

def render():
    direct=json.loads((ROOT/'artifacts/review_affine_green.json').read_text());old=json.loads((ROOT/'artifacts/revision_recovery_generalization.json').read_text());num=json.loads((ROOT/'artifacts/review_numpy_solver.json').read_text())
    from certified_results import compute,validate
    assert not validate(num),validate(num)
    rr=direct['rows'];assert len(rr)==240 and direct['complete'];groups={}
    for group,rows in [('eligible',[r for r in rr if r['eligible']]),('outside',[r for r in rr if not r['eligible']])]:
        groups[group]={'n':len(rows)}
        for arm in ['direct','refined']:
            good=[r for r in rows if r[arm]['ok']];timing=[r['direct_total_ms']+(r['refined']['ms'] if arm=='refined' else 0) for r in rows]
            groups[group][arm]=dict(accepted=len(good),median_gap_pct=float(np.median([100*r[arm]['relative_gap_upper'] for r in good])) if good else None,worst_gap_pct=max([100*r[arm]['relative_gap_upper'] for r in good],default=None),total_p50_ms=float(np.median(timing)),total_p99_ms=float(np.quantile(timing,.99)))
    common=[(a,b) for a,b in zip(rr,old['rows']) if a['direct']['ok'] and b['arms']['constructive']['ok']]
    c=dict(groups=groups,common_count=len(common),direct_vs_sdp_energy_pct=float(np.median([100*(a['direct']['cost']/b['arms']['constructive']['cost']-1) for a,b in common])),alternate_axis_eligible=sum(any(r['axis_eligible']) for r in rr if not r['eligible']),refinement_updates=sum(r['refined'].get('accepted_update',False) for r in rr),coordinate_abs_bound_max=max(r['direct']['control_box_abs_bound'] for r in rr if r['direct']['ok']),numpy=compute(num),numpy_intervals=sum(len(r.get('exact',{})) for r in num['rows']))
    e=groups['eligible'];o=groups['outside'];n=c['numpy']
    m=dict(DirectEligible=e['direct']['accepted'],DirectOutside=o['direct']['accepted'],DirectMedianMs=f"{e['direct']['total_p50_ms']:.1f}",DirectPnineMs=f"{e['direct']['total_p99_ms']:.1f}",DirectEnergyPct=f"{c['direct_vs_sdp_energy_pct']:.1f}",DirectCommon=c['common_count'],DirectWorstGap=f"{e['direct']['worst_gap_pct']:.1f}",RefineUpdates=c['refinement_updates'],RefineMedianMs=f"{e['refined']['total_p50_ms']:.1f}",RefineWorstGap=f"{e['refined']['worst_gap_pct']:.1f}",AlternateEligible=c['alternate_axis_eligible'],ExcursionBound=f"{c['coordinate_abs_bound_max']:.2f}",NumpyRatio=f"{n['median_ratio']:.2f}",NumpyFactorP=f"{n['factor']['time']['p50']:.2f}",NumpyRefP=f"{n['reference']['time']['p50']:.2f}",NumpyFactorTail=f"{n['factor']['time']['p99']:.2f}",NumpyRefTail=f"{n['reference']['time']['p99']:.2f}")
    (HERE/'results_peer_review.tex').write_text('% Generated by peer_review_results.py\n'+''.join('\\newcommand{\\'+k+'}{'+str(v)+'}\n' for k,v in m.items()));(HERE/'claims_peer_review.json').write_text(json.dumps(c,indent=2)+'\n');print(json.dumps({k:v for k,v in c.items() if k!='numpy'},indent=2));print(m)
if __name__=='__main__':render()
